/* ========================================
   KOFISHOOP — Style Sheet
   Nuansa coklat tenang, cozy, mahasiswa
   ======================================== */

/* ---------- RESET & BASE ---------- */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    font-size: 16px;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background-color: #FDF8F0;
    color: #2C1810;
    line-height: 1.7;
    overflow-x: hidden;
}

img {
    max-width: 100%;
    display: block;
}

a {
    text-decoration: none;
    color: inherit;
    transition: color 0.3s ease;
}

ul {
    list-style: none;
}

/* ---------- TYPOGRAPHY ---------- */
h1, h2, h3, h4 {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 600;
    line-height: 1.3;
}

/* ---------- CONTAINER ---------- */
.container {
    max-width: 1140px;
    margin: 0 auto;
    padding: 0 1.5rem;
}

/* ---------- BUTTONS ---------- */
.btn {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.85rem 2rem;
    border-radius: 50px;
    font-family: 'Inter', sans-serif;
    font-weight: 500;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.3s ease;
    border: 2px solid transparent;
}

.btn-primary {
    background: #6B4226;
    color: #fff;
    border-color: #6B4226;
}

.btn-primary:hover {
    background: #5D3A1A;
    border-color: #5D3A1A;
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(107, 66, 38, 0.3);
}

.btn-outline {
    background: transparent;
    color: #6B4226;
    border-color: #6B4226;
}

.btn-outline:hover {
    background: #6B4226;
    color: #fff;
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(107, 66, 38, 0.2);
}

.btn-full {
    width: 100%;
    justify-content: center;
}

/* ---------- SECTION ---------- */
.section {
    padding: 5rem 0;
}

.section-alt {
    background-color: #F5E6D3;
}

.section-header {
    text-align: center;
    margin-bottom: 3.5rem;
}

.section-label {
    display: inline-block;
    font-size: 0.8rem;
    font-weight: 500;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #C68642;
    margin-bottom: 0.75rem;
}

.section-title {
    font-size: 2.2rem;
    color: #2C1810;
    margin-bottom: 0.75rem;
}

.section-divider {
    width: 50px;
    height: 3px;
    background: #C68642;
    margin: 0 auto;
    border-radius: 2px;
}

.section-desc {
    color: #7D6B5A;
    max-width: 500px;
    margin: 1rem auto 0;
    font-size: 1rem;
}

/* ---------- SCROLL REVEAL ---------- */
.reveal {
    opacity: 0;
    transform: translateY(40px);
    transition: opacity 0.8s ease, transform 0.8s ease;
}

.reveal.visible {
    opacity: 1;
    transform: translateY(0);
}

/* ========================================
   NAVIGASI
   ======================================== */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    padding: 1rem 0;
    transition: all 0.4s ease;
    background: transparent;
}

.navbar.scrolled {
    background: rgba(253, 248, 240, 0.95);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 2px 20px rgba(44, 24, 16, 0.08);
    padding: 0.7rem 0;
}

.nav-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.nav-logo {
    font-family: 'Playfair Display', serif;
    font-size: 1.4rem;
    font-weight: 700;
    color: #FDF8F0;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: color 0.3s ease;
}

.nav-logo i {
    font-size: 1.2rem;
}

.navbar.scrolled .nav-logo {
    color: #6B4226;
}

.nav-menu {
    display: flex;
    gap: 2rem;
}

.nav-link {
    font-size: 0.9rem;
    font-weight: 400;
    color: rgba(253, 248, 240, 0.85);
    position: relative;
    padding: 0.25rem 0;
    transition: color 0.3s ease;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: #C68642;
    transition: width 0.3s ease;
}

.nav-link:hover {
    color: #fff;
}

.nav-link:hover::after {
    width: 100%;
}

.navbar.scrolled .nav-link {
    color: #7D6B5A;
}

.navbar.scrolled .nav-link:hover {
    color: #6B4226;
}

.navbar.scrolled .nav-link::after {
    background: #6B4226;
}

/* Toggle button (hamburger) */
.nav-toggle {
    display: none;
    flex-direction: column;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
}

.nav-toggle span {
    display: block;
    width: 24px;
    height: 2px;
    background: #FDF8F0;
    border-radius: 2px;
    transition: all 0.3s ease;
}

.navbar.scrolled .nav-toggle span {
    background: #6B4226;
}

.nav-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
    opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
}

/* ========================================
   HERO
   ======================================== */
.hero {
    position: relative;
    min-height: 100vh;
    display: flex;
    align-items: center;
    overflow: hidden;
}

.hero-bg {
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, #2C1810 0%, #5D3A1A 30%, #6B4226 60%, #8B5E3C 100%);
    z-index: 0;
    will-change: transform;
}

/* Pattern overlay */
.hero-bg::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
        radial-gradient(circle at 25% 25%, rgba(198, 134, 66, 0.08) 0%, transparent 50%),
        radial-gradient(circle at 75% 75%, rgba(198, 134, 66, 0.05) 0%, transparent 50%),
        url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23C68642' fill-opacity='0.04'%3E%3Ccircle cx='30' cy='30' r='1.5'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.hero-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to right, rgba(44, 24, 16, 0.6) 0%, rgba(44, 24, 16, 0.3) 100%);
    z-index: 1;
}

.hero-content {
    position: relative;
    z-index: 2;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
    padding-top: 5rem;
}

.hero-text {
    color: #FDF8F0;
}

.hero-badge {
    display: inline-block;
    font-size: 0.8rem;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #D4A56A;
    margin-bottom: 1rem;
    font-weight: 400;
}

.hero-title {
    font-size: 4rem;
    font-weight: 700;
    margin-bottom: 0.75rem;
    line-height: 1.1;
    color: #fff;
}

.hero-tagline {
    font-size: 1.2rem;
    font-weight: 300;
    color: #D4A56A;
    margin-bottom: 1rem;
}

.hero-desc {
    font-size: 1rem;
    color: rgba(253, 248, 240, 0.7);
    margin-bottom: 2rem;
    max-width: 450px;
}

.hero-actions {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.hero-actions .btn-outline {
    color: #FDF8F0;
    border-color: rgba(253, 248, 240, 0.4);
}

.hero-actions .btn-outline:hover {
    background: #FDF8F0;
    color: #6B4226;
    border-color: #FDF8F0;
}

/* Hero decoration */
.hero-decoration {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
}

.hero-circle {
    width: 320px;
    height: 320px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(198, 134, 66, 0.15) 0%, transparent 70%);
    border: 2px solid rgba(198, 134, 66, 0.2);
    animation: pulse 4s ease-in-out infinite;
}

.hero-circle-small {
    position: absolute;
    width: 200px;
    height: 200px;
    border-radius: 50%;
    border: 1px solid rgba(198, 134, 66, 0.15);
    animation: pulse 4s ease-in-out infinite 1s;
}

.hero-icon {
    position: absolute;
    font-size: 4rem;
    color: rgba(212, 165, 106, 0.6);
    animation: float 6s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 0.6; }
    50% { transform: scale(1.05); opacity: 1; }
}

@keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-15px); }
}

/* ========================================
   TENTANG
   ======================================== */
.about-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
}

.about-text p {
    color: #5D4A3A;
    margin-bottom: 1rem;
    font-size: 0.95rem;
}

.about-text p strong {
    color: #6B4226;
}

.about-values {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin-top: 2rem;
}

.value-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    background: rgba(107, 66, 38, 0.06);
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 500;
    color: #6B4226;
    transition: all 0.3s ease;
}

.value-item i {
    color: #C68642;
    font-size: 1.1rem;
}

.value-item:hover {
    background: rgba(107, 66, 38, 0.12);
    transform: translateY(-2px);
}

.about-image {
    display: flex;
    justify-content: center;
    align-items: center;
}

.about-img-box {
    width: 320px;
    height: 380px;
    border-radius: 20px;
    background: linear-gradient(135deg, #F5E6D3, #E8D5C0);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 1rem;
    position: relative;
    box-shadow: 0 20px 40px rgba(44, 24, 16, 0.1);
    transition: transform 0.4s ease;
}

.about-img-box:hover {
    transform: scale(1.02);
}

.about-img-box i {
    font-size: 5rem;
    color: #C68642;
    opacity: 0.6;
}

.about-img-label {
    font-family: 'Playfair Display', serif;
    font-size: 1.2rem;
    color: #8B5E3C;
    font-weight: 600;
}

/* ========================================
   LAYANAN
   ======================================== */
.services-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
}

.service-card {
    background: #FDF8F0;
    padding: 2rem 1.5rem;
    border-radius: 16px;
    text-align: center;
    transition: all 0.4s ease;
    border: 1px solid rgba(107, 66, 38, 0.06);
}

.service-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 30px rgba(44, 24, 16, 0.1);
    border-color: rgba(198, 134, 66, 0.2);
}

.service-icon {
    width: 64px;
    height: 64px;
    margin: 0 auto 1.25rem;
    background: linear-gradient(135deg, rgba(107, 66, 38, 0.08), rgba(198, 134, 66, 0.08));
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    color: #C68642;
    transition: all 0.4s ease;
}

.service-card:hover .service-icon {
    background: linear-gradient(135deg, #6B4226, #8B5E3C);
    color: #fff;
    transform: scale(1.1);
}

.service-title {
    font-size: 1.15rem;
    margin-bottom: 0.75rem;
    color: #2C1810;
}

.service-text {
    color: #7D6B5A;
    font-size: 0.88rem;
    line-height: 1.6;
}

/* ========================================
   GALERI
   ======================================== */
.gallery-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
}

.gallery-item {
    cursor: pointer;
    border-radius: 12px;
    overflow: hidden;
    transition: transform 0.4s ease, box-shadow 0.4s ease;
}

.gallery-item:hover {
    transform: scale(1.03);
    box-shadow: 0 12px 30px rgba(44, 24, 16, 0.15);
}

.gallery-placeholder {
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
    color: rgba(255, 255, 255, 0.4);
    border-radius: 12px;
    transition: transform 0.6s ease;
}

.gallery-item:hover .gallery-placeholder {
    transform: scale(1.05);
}

/* Lightbox */
.lightbox {
    position: fixed;
    inset: 0;
    background: rgba(44, 24, 16, 0.9);
    backdrop-filter: blur(8px);
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 2000;
    padding: 2rem;
}

.lightbox.active {
    display: flex;
}

.lightbox-content {
    text-align: center;
    animation: lightboxIn 0.4s ease;
}

@keyframes lightboxIn {
    from { transform: scale(0.8); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

.lightbox-placeholder {
    width: 300px;
    height: 300px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 4rem;
    color: rgba(255, 255, 255, 0.3);
    margin: 0 auto;
}

.lightbox-caption {
    margin-top: 1rem;
    color: rgba(255, 255, 255, 0.7);
    font-size: 1rem;
}

.lightbox-close {
    position: absolute;
    top: 1.5rem;
    right: 2rem;
    background: none;
    border: none;
    font-size: 2.5rem;
    color: rgba(255, 255, 255, 0.7);
    cursor: pointer;
    transition: color 0.3s ease;
    line-height: 1;
}

.lightbox-close:hover {
    color: #fff;
}

/* ========================================
   TESTIMONI
   ======================================== */
.testimoni-carousel {
    max-width: 700px;
    margin: 0 auto;
    overflow: hidden;
    position: relative;
}

.carousel-track {
    display: flex;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    will-change: transform;
}

.carousel-slide {
    min-width: 100%;
    padding: 0 0.5rem;
}

.testimoni-card {
    background: #FDF8F0;
    padding: 2.5rem 2rem;
    border-radius: 20px;
    text-align: center;
    box-shadow: 0 4px 20px rgba(44, 24, 16, 0.06);
}

.testimoni-stars {
    margin-bottom: 1rem;
    color: #C68642;
    font-size: 1rem;
    letter-spacing: 2px;
}

.testimoni-quote {
    font-size: 1.05rem;
    font-style: italic;
    color: #5D4A3A;
    line-height: 1.7;
    max-width: 550px;
    margin: 0 auto 1.5rem;
}

.testimoni-author {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    justify-content: center;
}

.testimoni-avatar {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6B4226, #8B5E3C);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 1.1rem;
}

.testimoni-author h4 {
    font-family: 'Inter', sans-serif;
    font-size: 0.95rem;
    font-weight: 600;
    color: #2C1810;
}

.testimoni-author span {
    font-size: 0.8rem;
    color: #7D6B5A;
}

/* Carousel navigation dots */
.carousel-nav {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    margin-top: 1.5rem;
}

.carousel-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #D4C4B0;
    border: none;
    cursor: pointer;
    transition: all 0.3s ease;
}

.carousel-dot.active {
    background: #6B4226;
    transform: scale(1.3);
}

.carousel-dot:hover {
    background: #8B5E3C;
}

/* ========================================
   KONTAK
   ======================================== */
.kontak-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: start;
}

/* Form */
.kontak-form {
    background: #fff;
    padding: 2.5rem;
    border-radius: 20px;
    box-shadow: 0 4px 20px rgba(44, 24, 16, 0.06);
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 500;
    color: #6B4226;
    margin-bottom: 0.4rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.85rem 1rem;
    border: 2px solid #E8D5C0;
    border-radius: 12px;
    font-family: 'Inter', sans-serif;
    font-size: 0.9rem;
    color: #2C1810;
    background: #FDF8F0;
    transition: all 0.3s ease;
    outline: none;
}

.form-group input:focus,
.form-group textarea:focus {
    border-color: #C68642;
    background: #fff;
    box-shadow: 0 0 0 4px rgba(198, 134, 66, 0.1);
}

.form-group input::placeholder,
.form-group textarea::placeholder {
    color: #B5A08C;
}

.form-group textarea {
    resize: vertical;
    min-height: 100px;
}

.form-toast {
    display: none;
    margin-top: 1rem;
    padding: 1rem 1.25rem;
    background: #E8F5E9;
    color: #2E7D32;
    border-radius: 12px;
    font-size: 0.9rem;
    font-weight: 500;
    text-align: center;
    gap: 0.5rem;
    align-items: center;
    justify-content: center;
}

.form-toast.show {
    display: flex;
}

.form-toast i {
    font-size: 1.2rem;
}

/* Info cards */
.kontak-info {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.info-card {
    display: flex;
    gap: 1rem;
    padding: 1.25rem;
    background: #fff;
