/* ========================================
   KOFISHOOP — JavaScript
   Interaktivitas & animasi
   ======================================== */

'use strict';

// =========================================
// 1. STICKY NAVIGATION
// =========================================
const navbar = document.getElementById('navbar');
const navToggle = document.getElementById('navToggle');
const navMenu = document.getElementById('navMenu');
const navLinks = document.querySelectorAll('.nav-link');

function updateNav() {
    if (window.scrollY > 80) {
        navbar.classList.add('scrolled');
    } else {
        navbar.classList.remove('scrolled');
    }
}

window.addEventListener('scroll', updateNav, { passive: true });
window.addEventListener('load', updateNav);

// =========================================
// 2. MOBILE HAMBURGER MENU
// =========================================
navToggle.addEventListener('click', () => {
    navToggle.classList.toggle('active');
    navMenu.classList.toggle('active');
});

// Tutup menu saat link diklik
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        navToggle.classList.remove('active');
        navMenu.classList.remove('active');
    });
});

// Tutup menu saat klik di luar
document.addEventListener('click', (e) => {
    if (!navbar.contains(e.target) && navMenu.classList.contains('active')) {
        navToggle.classList.remove('active');
        navMenu.classList.remove('active');
    }
});

// =========================================
// 3. SMOOTH SCROLL (fallback untuk Safari)
// =========================================
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href === '#') return;
        const target = document.querySelector(href);
        if (target) {
            e.preventDefault();
            const offset = navbar.offsetHeight;
            const targetPos = target.getBoundingClientRect().top + window.scrollY - offset;
            window.scrollTo({
                top: targetPos,
                behavior: 'smooth'
            });
        }
    });
});

// =========================================
// 4. SCROLL REVEAL (IntersectionObserver)
// =========================================
const revealElements = document.querySelectorAll('.reveal');

const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            // Optional: unobserve after reveal untuk performa
            // revealObserver.unobserve(entry.target);
        }
    });
}, {
    threshold: 0.15,
    rootMargin: '0px 0px -50px 0px'
});

revealElements.forEach(el => revealObserver.observe(el));

// =========================================
// 5. PARALLAX HERO
// =========================================
const heroBg = document.getElementById('heroBg');

function updateParallax() {
    if (window.innerWidth > 768) {
        const scrolled = window.scrollY;
        heroBg.style.transform = `translateY(${scrolled * 0.3}px)`;
    } else {
        heroBg.style.transform = 'translateY(0)';
    }
}

window.addEventListener('scroll', updateParallax, { passive: true });

// =========================================
// 6. TESTIMONI CAROUSEL
// =========================================
const carouselTrack = document.getElementById('carouselTrack');
const carouselDots = document.querySelectorAll('.carousel-dot');
const slides = document.querySelectorAll('.carousel-slide');
let currentSlide = 0;
let carouselInterval;

function goToSlide(index) {
    if (index < 0) index = slides.length - 1;
    if (index >= slides.length) index = 0;

    carouselTrack.style.transform = `translateX(-${index * 100}%)`;
    currentSlide = index;

    carouselDots.forEach(dot => dot.classList.remove('active'));
    carouselDots[index].classList.add('active');
}

function nextSlide() {
    goToSlide(currentSlide + 1);
}

function startCarousel() {
    stopCarousel();
    carouselInterval = setInterval(nextSlide, 5000);
}

function stopCarousel() {
    if (carouselInterval) {
        clearInterval(carouselInterval);
        carouselInterval = null;
    }
}

// Dot navigation
carouselDots.forEach(dot => {
    dot.addEventListener('click', () => {
        const slideIndex = parseInt(dot.getAttribute('data-slide'));
        goToSlide(slideIndex);
        resetCarousel();
    });
});

function resetCarousel() {
    stopCarousel();
    startCarousel();
}

// Pause on hover
const carousel = document.querySelector('.testimoni-carousel');
carousel.addEventListener('mouseenter', stopCarousel);
carousel.addEventListener('mouseleave', startCarousel);

// Touch support
let touchStartX = 0;
let touchEndX = 0;

carousel.addEventListener('touchstart', (e) => {
    touchStartX = e.changedTouches[0].screenX;
    stopCarousel();
}, { passive: true });

carousel.addEventListener('touchend', (e) => {
    touchEndX = e.changedTouches[0].screenX;
    const diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
        if (diff > 0) goToSlide(currentSlide + 1);
        else goToSlide(currentSlide - 1);
    }
    startCarousel();
}, { passive: true });

// Init carousel
goToSlide(0);
startCarousel();

// =========================================
// 7. FORM HANDLING
// =========================================
const kontakForm = document.getElementById('kontakForm');
const formToast = document.getElementById('formToast');

kontakForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const nama = document.getElementById('nama').value.trim();
    const email = document.getElementById('email').value.trim();
    const pesan = document.getElementById('pesan').value.trim();

    // Validasi
    if (!nama || !email || !pesan) {
        alert('Harap isi semua bidang!');
        return;
    }

    // Validasi email sederhana
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        alert('Mohon masukkan alamat email yang valid.');
        return;
    }

    // Tampilkan toast sukses
    formToast.classList.add('show');
    kontakForm.reset();

    // Sembunyikan toast setelah 5 detik
    setTimeout(() => {
        formToast.classList.remove('show');
    }, 5000);
});

// =========================================
// 8. LIGHTBOX GALERI
// =========================================
const galleryItems = document.querySelectorAll('.gallery-item');
const lightbox = document.getElementById('lightbox');
const lightboxClose = document.getElementById('lightboxClose');
const lightboxImg = document.getElementById('lightboxImg');
const lightboxCaption = document.getElementById('lightboxCaption');

const galleryData = [
    { img: 'images/gallery-1.jpg', label: 'Kopnikmat Pagi Hari' },
    { img: 'images/gallery-2.jpg', label: 'Latigrafi &amp; Cita Rasa' },
    { img: 'images/gallery-3.jpg', label: 'Suasana Belajar' },
    { img: 'images/gallery-4.jpg', label: 'Diskusi &amp; Kumpul' },
    { img: 'images/gallery-5.jpg', label: 'Ruang Nugas' },
    { img: 'images/gallery-6.jpg', label: 'Live Music Akustik' }
];

galleryItems.forEach((item, index) => {
    item.addEventListener('click', () => {
        const data = galleryData[index];
        lightboxImg.style.backgroundImage = `url('${data.img}')`;
        lightboxCaption.innerHTML = data.label;
        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
        stopCarousel();
    });
});

        lightboxPlaceholder.style.background = bg;
        lightboxPlaceholder.innerHTML = `<i class="fas ${data.icon}"></i>`;
        lightboxCaption.textContent = data.label;

        lightbox.classList.add('active');
        document.body.style.overflow = 'hidden';
        stopCarousel();
    });
});

function closeLightbox() {
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
    startCarousel();
}

lightboxClose.addEventListener('click', closeLightbox);

// Tutup lightbox klik di luar konten
lightbox.addEventListener('click', (e) => {
    if (e.target === lightbox) {
        closeLightbox();
    }
});

// Tutup lightbox dengan tombol Escape
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lightbox.classList.contains('active')) {
        closeLightbox();
    }
});

// =========================================
// 9. RESIZE HANDLER
// =========================================
let resizeTimer;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
        // Update parallax on resize
        updateParallax();
        // Re-check nav
        if (window.innerWidth > 768 && navMenu.classList.contains('active')) {
            navToggle.classList.remove('active');
            navMenu.classList.remove('active');
        }
    }, 250);
});

