// =========================================
const heroBg = document.getElementById('heroBg');
const heroContent = document.querySelector('.hero-content');
const sectionAlts = document.querySelectorAll('.section-alt');
const serviceCards = document.querySelectorAll('.service-card');
const aboutImage = document.querySelector('.about-img-box');
const footer = document.querySelector('.footer');

let scrollVelocity = 0;
let lastScrollY = 0;
let rafId = null;

// Smooth parallax update dengan velocity easing
function updateParallax() {
    const scrolled = window.scrollY;
    const viewH = window.innerHeight;
    const isMobile = window.innerWidth <= 768;

    if (!isMobile) {
        // Hero background — gerak lambat (20%)
        heroBg.style.transform = `translateY(${scrolled * 0.2}px)`;

        // Hero content — gerak lebih cepat (40%) untuk depth
        heroContent.style.transform = `translateY(${scrolled * 0.08}px)`;

        // Section alt backgrounds — parallax subtle
        sectionAlts.forEach(section => {
            const rect = section.getBoundingClientRect();
            const center = rect.top + rect.height / 2;
            const progress = center / viewH;
            if (progress > -0.5 && progress < 1.5) {
                section.style.backgroundPosition = `center ${50 + (progress - 0.5) * 8}%`;
            }
        });
    } else {
        heroBg.style.transform = 'translateY(0)';
        heroContent.style.transform = 'translateY(0)';
    }
}

// Velocity-based scroll: elemen bergerak dengan kecepatan berbeda
function velocityScroll() {
    const currentY = window.scrollY;
    scrollVelocity = currentY - lastScrollY;
    lastScrollY = currentY;

    if (window.innerWidth > 768) {
        // Service cards: sedikit bergerak berdasarkan arah scroll
        serviceCards.forEach((card, i) => {
            const rect = card.getBoundingClientRect();
            if (rect.top < window.innerHeight && rect.bottom > 0) {
                const speed = 0.3 + (i * 0.1);
                const offset = scrollVelocity * speed * 0.3;
                card.style.transform = `translateY(${offset}px)`;
                // Kembali ke posisi semula dengan transisi
                clearTimeout(card._velocityTimer);
                card._velocityTimer = setTimeout(() => {
                    card.style.transform = '';
                }, 150);
            }
        });
    }

    rafId = null;
}

// Gabungkan parallax + velocity dalam satu scroll handler
window.addEventListener('scroll', () => {
    updateParallax();

    // Velocity scroll via requestAnimationFrame
    if (!rafId) {
        rafId = requestAnimationFrame(velocityScroll);
    }
}, { passive: true });

