input.new_string:
// =========================================
// 4. ADVANCED SCROLL REVEAL — staggered + directional + scale
// =========================================
const allRevealElements = document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .reveal-scale');

const revealObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            // Add visible class with a small random delay for organic feel
            const delay = parseFloat(entry.target.dataset.delay) || 0;
            setTimeout(() => {
                entry.target.classList.add('visible');
            }, delay * 1000);
        }
    });
}, {
    threshold: 0.15,
    rootMargin: '0px 0px -80px 0px'
});

allRevealElements.forEach(el => revealObserver.observe(el));

// =========================================
// 4b. SCROLL PROGRESS INDICATOR
// =========================================
const scrollProgress = document.createElement('div');
scrollProgress.className = 'scroll-progress';
scrollProgress.innerHTML = '<div class="scroll-progress-bar" id="scrollProgressBar"></div>';
document.body.appendChild(scrollProgress);

function updateScrollProgress() {
    const scrollTop = window.scrollY;
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const progress = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    const bar = document.getElementById('scrollProgressBar');
    if (bar) bar.style.width = progress + '%';
}
window.addEventListener('scroll', updateScrollProgress, { passive: true });
window.addEventListener('load', updateScrollProgress);

