.nav-menu {
    display: flex;
    gap: 2rem;
}

.nav-link {
    font-size: 0.9rem;
    font-weight: 400;
    color: rgba(253, 248, 240, 0.85);
    position: relative;
    padding: 0.25rem 0;
    transition: color 0.3s ease;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: #C68642;
    transition: width 0.3s ease;
}

.nav-link:hover {
    color: #fff;
}

.nav-link:hover::after {
    width: 100%;
}

.navbar.scrolled .nav-link {
    color: #7D6B5A;
}

.navbar.scrolled .nav-link:hover {
    color: #6B4226;
}

.navbar.scrolled .nav-link::after {
    background: #6B4226;
}

/* Toggle button (hamburger) */
.nav-toggle {
    display: none;
    flex-direction: column;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
}

.nav-toggle span {
    display: block;
    width: 24px;
    height: 2px;
    background: #FDF8F0;
    border-radius: 2px;
    transition: all 0.3s ease;
}

.navbar.scrolled .nav-toggle span {
    background: #6B4226;
}

.nav-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
    opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
}

