   ======================================== */

/* Service Tabs */
.service-tabs {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}
.service-tab {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1.5rem;
    border-radius: 50px;
    border: 2px solid rgba(107, 66, 38, 0.12);
    background: transparent;
    color: #7D6B5A;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    font-family: 'Inter', sans-serif;
}
.service-tab i {
    font-size: 1rem;
    color: #C68642;
    transition: color 0.3s;
}
.service-tab:hover {
    border-color: #C68642;
    color: #6B4226;
    transform: translateY(-2px);
}
.service-tab.active {
    background: #6B4226;
    border-color: #6B4226;
    color: #fff;
    box-shadow: 0 6px 20px rgba(107, 66, 38, 0.25);
}
.service-tab.active i {
    color: #fff;
}

/* Service Panels */
.service-panels {
    position: relative;
    min-height: 300px;
}
.service-panel {
    display: none;
    animation: panelFadeIn 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.service-panel.active {
    display: block;
}
@keyframes panelFadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Panel Grid Layout */
.panel-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    align-items: center;
    background: #FDF8F0;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 8px 30px rgba(44, 24, 16, 0.08);
}

.panel-image {
    height: 350px;
    background-size: cover;
    background-position: center;
    border-radius: 20px 0 0 20px;
}

.panel-info {
    padding: 2.5rem 2.5rem 2.5rem 0;
}
.panel-title {
    font-size: 1.5rem;
    color: #2C1810;
    margin-bottom: 0.75rem;
}
.panel-desc {
    color: #7D6B5A;
    font-size: 0.9rem;
    line-height: 1.7;
    margin-bottom: 1.5rem;
}

/* Highlights list */
.panel-highlights {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    margin-bottom: 1.5rem;
}
.panel-highlight {
    display: flex;
    align-items: center;
    gap: 1rem;
}
.hl-icon {
    width: 44px;
    height: 44px;
    background: linear-gradient(135deg, rgba(107, 66, 38, 0.08), rgba(198, 134, 66, 0.08));
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #C68642;
    font-size: 1.1rem;
    flex-shrink: 0;
}
.panel-highlight strong {
    display: block;
    font-size: 0.9rem;
    color: #2C1810;
    font-family: 'Inter', sans-serif;
    font-weight: 600;
}
.panel-highlight small {
    font-size: 0.78rem;
    color: #7D6B5A;
}

/* Price tag */
.panel-price {
    font-size: 0.85rem;
    color: #6B4226;
    padding: 0.6rem 1rem;
    background: rgba(198, 134, 66, 0.1);
    border-radius: 10px;
    display: inline-block;
}
.panel-price strong {
    color: #C68642;
}

