/* ========================================
   GALERI — FEATURED + CARD GRID
   ======================================== */
.gallery-layout {
    display: grid;
    grid-template-columns: 1.4fr 0.6fr 0.6fr;
    grid-template-rows: auto auto;
    gap: 0.8rem;
}

/* Featured large item — spans left column, full height */
.gallery-featured {
    grid-row: 1 / 3;
    cursor: pointer;
    border-radius: 16px;
    overflow: hidden;
    position: relative;
}
.gallery-featured-img {
    height: 100%;
    min-height: 420px;
    background-size: cover;
    background-position: center;
    border-radius: 16px;
    position: relative;
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.gallery-featured:hover .gallery-featured-img {
    transform: scale(1.05);
}
.gallery-featured-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(44, 24, 16, 0.75) 0%, transparent 50%);
    border-radius: 16px;
    display: flex;
    align-items: flex-end;
    padding: 2rem;
}
.gallery-featured-label h3 {
    font-size: 1.5rem;
    color: #fff;
    margin: 0.5rem 0 0.25rem;
}
.gallery-featured-label p {
    font-size: 0.85rem;
    color: rgba(255,255,255,0.7);
    margin: 0;
}

/* Tag pills */
.gallery-featured-tag,
.gallery-card-tag {
    display: inline-block;
    font-size: 0.7rem;
    font-weight: 500;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #C68642;
    background: rgba(253, 248, 240, 0.15);
    backdrop-filter: blur(4px);
    padding: 0.25rem 0.75rem;
    border-radius: 50px;
    border: 1px solid rgba(253, 248, 240, 0.2);
}

/* Small cards */
.gallery-card {
    cursor: pointer;
    border-radius: 16px;
    overflow: hidden;
    position: relative;
}
.gallery-card-tall {
    grid-column: 2 / 4;
}
.gallery-card-img {
    height: 200px;
    background-size: cover;
    background-position: center;
    transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    border-radius: 16px;
    position: relative;
}
.gallery-card:hover .gallery-card-img {
    transform: scale(1.05);
}
.gallery-card-overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(44, 24, 16, 0.7) 0%, transparent 45%);
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: 1.25rem;
}
.gallery-card-overlay h4 {
    font-family: 'Inter', sans-serif;
    font-size: 0.9rem;
    color: #fff;
    margin: 0.5rem 0 0;
    font-weight: 500;
}
.gallery-card-tag {
    align-self: flex-start;
}

